add_filter( 'woocommerce_my_account_my_orders_query', 'perfectpixel_hide_statuses_in_my_account', 20 );

function perfectpixel_hide_statuses_in_my_account( $args ) {
	$hidden = array_filter( array_map( 'sanitize_key', explode( ',', '{{my_account_hidden_statuses}}' ) ) );
	if ( ! $hidden ) {
		return $args;
	}
	$all = array_map(
		function ( $key ) {
			return substr( $key, 3 );
		},
		array_keys( wc_get_order_statuses() )
	);
	$current        = ! empty( $args['status'] ) ? (array) $args['status'] : $all;
	$args['status'] = array_values( array_diff( $current, $hidden ) );
	return $args;
}
